describe('Password Change from Profile Settings', () => {
  beforeEach(() => {
    cy.visit('/profile');
  });

  it('should successfully change password with valid input', () => {
    // Verify initial password is displayed
    cy.get('[data-testid="current-password-input"]').should('be.visible');
    cy.get('[data-testid="current-password-input"]').type('oldPassword123');

    // Verify password change button is enabled
    cy.get('[data-testid="change-password-button"]').should('be.visible');

    // Click change password button
    cy.get('[data-testid="change-password-button"]').click();

    // Verify password fields are visible
    cy.get('[data-testid="new-password-input"]').should('be.visible');
    cy.get('[data-testid="new-password-input"]').type('NewSecurePassword123');

    cy.get('[data-testid="confirm-password-input"]').should('be.visible');
    cy.get('[data-testid="confirm-password-input"]').type('NewSecurePassword123');

    // Verify password strength validation
    cy.get('[data-testid="password-strength-indicator"]').should('be.visible');
    cy.get('[data-testid="password-strength-indicator"]').should('contain', 'Strong');

    // Verify password change button is enabled
    cy.get('[data-testid="change-password-button"]').should('be.visible');

    // Click change password button
    cy.get('[data-testid="change-password-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Password changed successfully');

    // Verify old password field is cleared
    cy.get('[data-testid="current-password-input"]').should('not.exist');

    // Verify profile page is still visible
    cy.get('[data-testid="profile-header"]').should('be.visible');
  });

  it('should display error when confirm password does not match', () => {
    // Verify initial password is displayed
    cy.get('[data-testid="current-password-input"]').should('be.visible');
    cy.get('[data-testid="current-password-input"]').type('oldPassword123');

    // Verify password change button is enabled
    cy.get('[data-testid="change-password-button"]').should('be.visible');

    // Click change password button
    cy.get('[data-testid="change-password-button"]').click();

    // Verify new password fields are visible
    cy.get('[data-testid="new-password-input"]').should('be.visible');
    cy.get('[data-testid="new-password-input"]').type('NewSecurePassword123');

    // Verify confirm password field is visible
    cy.get('[data-testid="confirm-password-input"]').should('be.visible');

    // Type different password in confirm field
    cy.get('[data-testid="confirm-password-input"]').type('IncorrectPassword123');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Passwords do not match');

    // Verify password change button is disabled
    cy.get('[data-testid="change-password-button"]').should('be.disabled');

    // Verify old password field is still visible
    cy.get('[data-testid="current-password-input"]').should('be.visible');
  });
});
